import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Arrow Calculus Kernel","description":"","frontmatter":{"title":"Arrow Calculus Kernel","type":"adr","date":"2026-08-31T00:00:00.000Z","status":"accepted","status_note":"Accepted — `app` is the primitive; the calculus is the only execution path."},"headers":[],"relativePath":"handl/project/adrs/0052-arrow-calculus-kernel.md","filePath":"vendored/handl/project/adrs/0052-arrow-calculus-kernel.md"}'),a={name:`handl/project/adrs/0052-arrow-calculus-kernel.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0052-arrow-calculus-kernel" tabindex="-1">ADR-0052: Arrow Calculus Kernel <a class="header-anchor" href="#adr-0052-arrow-calculus-kernel" aria-label="Permalink to “ADR-0052: Arrow Calculus Kernel”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong><code>app</code> is the primitive; interpretation is the only execution mechanism.</strong></li><li><strong>Semantic principle: arrows are values</strong> and computation is composition — no implicit environment or evaluation-by-name.</li><li><strong>Kernel representation</strong>: <code>Term</code>/<code>Value</code> with the arrow constructors (<code>id</code>, <code>compose</code>, product, curry, …); a closed term is a value.</li><li><strong>The lowering table (surface construct → arrow form) is normative</strong>: every construct is defined by the arrow it lowers to.</li><li><strong>Derived forms</strong> (<code>let</code>, <code>if</code>, loops) are sugar over the kernel, not primitives.</li><li><strong><code>proc</code> notation and <code>x = y</code> binding are the authoring surface</strong>; they lower to arrows like any other sugar.</li><li><strong>Big-bang migration</strong>: one cutover, the old <code>Scheme</code> removed, no dual path.</li><li><strong>Handlers are outside the calculus</strong>; execution is one interpretation of the arrow.</li><li><strong>Feedback semantics</strong> (causal/strict vs lazy/fixpoint) are specified separately, never assumed.</li><li><strong>Scope</strong>: kernel + bootstrap + canonical <code>proc</code> surface; everything else derives.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The language had several execution paths and a binding model inside the kernel, so the same program could mean different things depending on which path ran it. One primitive plus a lowering table closes the calculus: every construct has exactly one arrow reading.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep the old <code>Scheme</code> beside the kernel</strong> — two execution paths, two semantics.</li><li><strong>Put handlers inside the calculus</strong> — handlers interpret arrows; they are not arrow constructors.</li><li><strong>Assume one feedback semantics</strong> — causal and lazy fixpoint differ; the language picks per definition.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Every surface form must lower; a construct with no arrow reading is not in the language.</li><li>The bootstrap and <code>proc</code> surface are canonical; other syntax is sugar.</li><li>Handlers stay external and composable.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>kernel/</code> — <code>Term</code>/<code>Value</code> and the arrow constructors.</li><li><code>crates/handl-kit-data-canonical/data/eval.yaml</code> — the schemes.</li><li><code>engine-exec-*</code> — the interpreters that agree value-for-value.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The lowering table, <code>proc</code> surface, handlers and feedback semantics: +<a href="./../design/0052-arrow-calculus-kernel.html"><code>design/0052-arrow-calculus-kernel.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};